SYSTEM SYNC REPLICA t;
SYSTEM SYNC REPLICA db.t;
SYSTEM SYNC REPLICA ON CLUSTER c db.t;
SYSTEM SYNC REPLICA db.t IF EXISTS;
SYSTEM SYNC REPLICA db.t STRICT;
SYSTEM SYNC REPLICA db.t IF EXISTS PULL;
SYSTEM SYNC REPLICA db.t LIGHTWEIGHT;
SYSTEM SYNC REPLICA ON CLUSTER 'c' db.t LIGHTWEIGHT FROM 'r1', 'r2';
SYSTEM SYNC DATABASE REPLICA db;
SYSTEM SYNC DATABASE REPLICA ON CLUSTER c db;
SYSTEM SYNC TRANSACTION LOG;
SYSTEM SYNC TRANSACTION LOG ON CLUSTER c;
SYSTEM SYNC FILE CACHE;
SYSTEM SYNC FILESYSTEM CACHE;
SYSTEM SYNC FILESYSTEM CACHE 'c1' ON CLUSTER c;
